#!/usr/bin/env python3
"""Offline paper figures from completed non-defense results only."""
import csv,sqlite3
from pathlib import Path
import matplotlib.pyplot as plt
import pandas as pd
import torch
ROOT=Path(__file__).resolve().parents[1]; FIG=ROOT/'experiments/figures/paper_selected_figures'; SUM=ROOT/'experiments/summaries/paper_selected_figures';R=[110,150,180,200,240,250]
def db(p):
 with sqlite3.connect(p)as c:z=c.execute('select round_index,clean_accuracy,attack_success_rate from round_metrics order by round_index').fetchall()
 return {r:(a,s)for r,a,s in z}
def save(fig,n):
 FIG.mkdir(parents=True,exist_ok=True)
 for e in('png','pdf'):fig.savefig(FIG/f'{n}.{e}',bbox_inches='tight',dpi=180)
 plt.close(fig)
def curve(series,title,name,y='ASR (%)'):
 fig,ax=plt.subplots(figsize=(7,4))
 for label,d in series.items():ax.plot(range(60,251),[d.get(r,(None,None))[1]for r in range(60,251)],label=label)
 ax.axvspan(60,110,color='gray',alpha=.15,label='Attack stage');ax.set(xlabel='Global Round',ylabel=y,title=title);ax.legend(fontsize=8);ax.grid(alpha=.25);save(fig,name)
def main():
 sources={'DBA':ROOT/'outputs/paper100_extra250/extra250_01_dba_baseline/metrics_extra250_01_dba_baseline.db','Neurotoxin-UAP':ROOT/'outputs/paper100_extra250/extra250_02_neurotoxin_uap/metrics_extra250_02_neurotoxin_uap.db','CE-UAP':ROOT/'outputs/paper100_mechanism250/mech250_01_ce_only_uap/metrics_mech250_01_ce_only_uap.db','PBU (Ours)':ROOT/'outputs/paper100_mechanism250/mech250_03_proto_uap_layer4/metrics_mech250_03_proto_uap_layer4.db'}
 data={k:db(v)for k,v in sources.items() if v.exists()};curve(data,'Main ASR persistence','fig5_1_main_asr_round_curve')
 fm=pd.read_csv(ROOT/'experiments/summaries/paper100_mechanism250/feature_mechanism250_summary.csv');fig,axs=plt.subplots(1,2,figsize=(9,3.5))
 for exp,g in fm.groupby('experiment_id'):
  q=g.groupby('round')[['target_sim','feature_margin']].mean();axs[0].plot(q.index,q.target_sim,marker='o',label=exp);axs[1].plot(q.index,q.feature_margin,marker='o',label=exp)
 axs[0].set_title('(a) Target similarity');axs[1].set_title('(b) Target-source margin')
 for a in axs:a.set_xlabel('Round');a.grid(alpha=.25);a.legend(fontsize=7)
 save(fig,'fig6_2_feature_mechanism')
 la=pd.read_csv(ROOT/'experiments/summaries/paper100_lambda_long200/paper100_lambda_long200_summary.csv');po=pd.read_csv(ROOT/'experiments/summaries/paper100_poison_long200/paper100_poison_long200_summary.csv');fig,axs=plt.subplots(1,2,figsize=(9,3.5));axs[0].plot(la.lambda_delta,la['ASR@200'],marker='o');axs[0].set(xlabel='lambda_delta',ylabel='ASR@200 (%)');axs[1].plot(po.poison_ratio,po['AUC@110-200'],marker='o');axs[1].set(xlabel='Poison ratio',ylabel='AUC@110-200');[a.grid(alpha=.25)for a in axs];save(fig,'fig6_3_sensitivity_summary')
 # ablation: use completed 250-round CE/proposed and extra250-style 250 ablation DBs when present
 ab={'CE-only':sources['CE-UAP'],'Delta + Train':sources['PBU (Ours)'],'Delta only':ROOT/'outputs/paper100_final310/p100f_ablation_delta_only/metrics_p100f_ablation_delta_only.db','Train only':ROOT/'outputs/paper100_final310/p100f_ablation_train_only/metrics_p100f_ablation_train_only.db'}
 vals=[]
 for n,p in ab.items():
  d=db(p);pts=[(r,d[r][1])for r in sorted(d)if 110<=r<=250 and d[r][1]is not None];v=sum((b[0]-a[0])*(a[1]+b[1])/2 for a,b in zip(pts,pts[1:]))/(pts[-1][0]-110)if len(pts)>1 else None;vals.append((n,v))
 fig,ax=plt.subplots(figsize=(6,4));ax.bar([x[0]for x in vals],[x[1]for x in vals]);ax.set_ylabel('PA-AUC');ax.tick_params(axis='x',rotation=25);save(fig,'fig6_1_ablation_paauc_bar')
 rows=[{'figure':n,'path':str((FIG/f'{n}.png').relative_to(ROOT))}for n in('fig5_1_main_asr_round_curve','fig6_1_ablation_paauc_bar','fig6_2_feature_mechanism','fig6_3_sensitivity_summary')];SUM.mkdir(parents=True,exist_ok=True)
 with(SUM/'paper_selected_figures_manifest.csv').open('w',newline='')as h:w=csv.DictWriter(h,['figure','path']);w.writeheader();w.writerows(rows)
 (SUM/'paper_selected_figures_report.md').write_text('# Selected paper figures\n\nGenerated offline from completed mechanism250, extra250, lambda-long200, poison-long200 and completed ablation DBs. No defense250 output was read or written. Fig. 5.2 UAP visualization is not generated by this script; it requires loading local CIFAR test samples and is intentionally left as a separate offline artifact.\n')
if __name__=='__main__':main()
